import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"诸天角色推演","description":"以锚点共生文明框架复盘诸天角色：带土、柱间、斑、叶凡、石昊——谁走掠夺路，谁具共生心。","frontmatter":{"title":"诸天角色推演","description":"以锚点共生文明框架复盘诸天角色：带土、柱间、斑、叶凡、石昊——谁走掠夺路，谁具共生心。"},"headers":[],"relativePath":"multiverse/index.md","filePath":"multiverse/index.md"}'),o={name:"multiverse/index.md"};function i(l,t,h,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="诸天角色推演" tabindex="-1">诸天角色推演 <a class="header-anchor" href="#诸天角色推演" aria-label="Permalink to &quot;诸天角色推演&quot;">​</a></h1><blockquote><p>以<strong>锚点共生文明</strong>的世界观框架，复盘诸天万界的知名角色：他们的力量从何而来、资源如何分配、文明走向何方。这不是战力排行，而是<strong>路线判别</strong> —— 谁在走<strong>掠夺</strong>之路，谁心怀<strong>共生</strong>之种。</p></blockquote><h2 id="推演方法论" tabindex="-1">推演方法论 <a class="header-anchor" href="#推演方法论" aria-label="Permalink to &quot;推演方法论&quot;">​</a></h2><p>把任意角色放进衡元宙的坐标系，只需回答四个问题：</p><table tabindex="0"><thead><tr><th>维度</th><th>判别问题</th><th>掠夺型倾向</th><th>共生型倾向</th></tr></thead><tbody><tr><td>力量来源</td><td>力量是否以他人为代价？</td><td>吞噬、夺取、奴役、垄断法门</td><td>自生自长、循环交换、开放共享</td></tr><tr><td>资源逻辑</td><td>资源是猎场还是循环？</td><td>涸泽而渔、零和博弈</td><td>做大蛋糕、能量循环</td></tr><tr><td>弱者关系</td><td>强者如何对待弱者？</td><td>踏脚石、工具、牧群</td><td>责任者、引导者、同行者</td></tr><tr><td>文明上限</td><td>体系能否自我延续？</td><td>本源不纯、熵增崩塌、文明断层</td><td>集体升维、星际共生、无上限</td></tr></tbody></table><p>四条标准，两条路线，一眼可辨。</p><h2 id="角色推演索引" tabindex="-1">角色推演索引 <a class="header-anchor" href="#角色推演索引" aria-label="Permalink to &quot;角色推演索引&quot;">​</a></h2><h3 id="🌊-火影忍者-·-木叶系" tabindex="-1">🌊 火影忍者 · 木叶系 <a class="header-anchor" href="#🌊-火影忍者-·-木叶系" aria-label="Permalink to &quot;🌊 火影忍者 · 木叶系&quot;">​</a></h3><ul><li><a href="./naruto-obito">宇智波带土 —— 掠夺式救世的悖论</a></li><li><a href="./naruto-hashirama">千手柱间 —— 未成体系的共生主义者</a></li><li><a href="./naruto-madara">宇智波斑 —— 极限掠夺者的法则壁垒</a></li></ul><h3 id="📖-遮天-·-完美世界" tabindex="-1">📖 遮天 · 完美世界 <a class="header-anchor" href="#📖-遮天-·-完美世界" aria-label="Permalink to &quot;📖 遮天 · 完美世界&quot;">​</a></h3><ul><li><a href="./zhetian-ye-fan">叶凡 —— 帝路独木桥上的众生守护者</a></li><li><a href="./wanmei-shi-hao">石昊 —— 被掠夺者点燃的万族旗手</a></li></ul><h2 id="一句话总览" tabindex="-1">一句话总览 <a class="header-anchor" href="#一句话总览" aria-label="Permalink to &quot;一句话总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>原作路线判定</th><th>锚点视角判词</th></tr></thead><tbody><tr><td>带土</td><td>掠夺式救世（精神奴役型）</td><td>共生潜力被掠夺体系污染，执念能量用错了方向</td></tr><tr><td>柱间</td><td>朴素共生（未制度化）</td><td>有共生之心，缺共生之宪，无力抵御掠夺体系反扑</td></tr><tr><td>斑</td><td>极致掠夺（精英主义）</td><td>本源不纯者，永触不到宇宙本源，困在掠夺循环</td></tr><tr><td>叶凡</td><td>底色上的守护者</td><td>最接近共生位面至高者的独行者，跳出掠夺执念</td></tr><tr><td>石昊</td><td>以战养战、本质守护</td><td>天生的锚点守护者，万族共进的旗手，挣脱掠夺轮回</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">说明</p><p>本板块为基于公开作品设定的同人思想实验，仅以&quot;掠夺 × 共生&quot;框架做路线推演，不构成对原作与角色的定论；若与原作设定出入，以原作为准。</p></div>',14)])])}const m=a(o,[["render",i]]);export{b as __pageData,m as default};
